import React, { useMemo, useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

const FALLBACK_IMAGE =
  'https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?auto=format&fit=crop&w=800&q=80';

const Home = ({ wishlist = [], onAddToWishlist, onRemoveFromWishlist }) => {

  const categories = [
    { name: 'All', icon: '🎯' },
    { name: 'Books', icon: '📚' },
    { name: 'Notes', icon: '📝' },
    { name: 'Gadgets', icon: '⚙️' },
    { name: 'Electronics', icon: '🔌' },
    { name: 'Laptops', icon: '💻' },
    { name: 'Phones', icon: '📱' },
    { name: 'Accessories', icon: '🎧' },
    { name: 'Stationery', icon: '✏️' },
    { name: 'Bags', icon: '🎒' },
    { name: 'Calculators', icon: '🧮' },
    { name: 'Lab Equipment', icon: '🔬' },
    { name: 'Sports', icon: '⚽' },
    { name: 'Fashion', icon: '👕' },
    { name: 'Hostel Items', icon: '🛏️' },
    { name: 'Furniture', icon: '🪑' },
    { name: 'Cycles', icon: '🚴' },
    { name: 'Projects', icon: '🛠️' },
    { name: 'Coding Resources', icon: '💾' },
    { name: 'Tuition', icon: '👨‍🏫' },
    { name: 'Services', icon: '🤝' },
    { name: 'Others', icon: '🎁' }
  ];

  const products = [
    { id: 37, title: 'College T-Shirt Pack 3', price: '28', category: 'Fashion', badge: 'Fashion', image: 'https://images.unsplash.com/photo-1521572163474-6864f9cf17ab' },
    { id: 38, title: 'Casual Jacket Denim', price: '59', category: 'Fashion', badge: 'Fashion', image: 'https://images.unsplash.com/photo-1551028719-00167b16ebc5' },
    { id: 39, title: 'Formal Shirt Premium Cotton', price: '49', category: 'Fashion', badge: 'Fashion', image: 'https://images.unsplash.com/photo-1596399579883-4c88c5e49ec2' },
    { id: 40, title: 'Twin XL Bed Sheet Set', price: '25', category: 'Hostel Items', badge: 'Hostel Items', image: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d' },
    { id: 41, title: 'Microfiber Pillow', price: '22', category: 'Hostel Items', badge: 'Hostel Items', image: 'https://images.unsplash.com/photo-1584622181563' },
    { id: 42, title: 'Electric Kettle', price: '32', category: 'Hostel Items', badge: 'Hostel Items', image: 'https://images.unsplash.com/photo-1578500494198' }
  ];

  const [activeCategory, setActiveCategory] = useState('All');
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState('latest');
  const [loading, setLoading] = useState(false);
  const [failedImages, setFailedImages] = useState(new Set());

  const handleImageError = (id) => {
    setFailedImages(prev => new Set([...prev, id]));
  };

  const getImage = (product) => {
    return failedImages.has(product.id) || !product.image
      ? FALLBACK_IMAGE
      : product.image;
  };

  const isWishlisted = (id) =>
    wishlist.some((p) => p.id === id);

  const toggleWishlist = (product) => {
    if (isWishlisted(product.id)) {
      onRemoveFromWishlist(product.id);
    } else {
      onAddToWishlist(product);
    }
  };

  const filteredProducts = useMemo(() => {
    let result = products.filter(p =>
      (activeCategory === 'All' || p.category === activeCategory) &&
      p.title.toLowerCase().includes(search.toLowerCase())
    );

    if (sortBy === 'price-low')
      result.sort((a, b) => a.price - b.price);
    if (sortBy === 'price-high')
      result.sort((a, b) => b.price - a.price);

    return result;
  }, [activeCategory, search, sortBy]);

  useEffect(() => {
    setLoading(true);
    const t = setTimeout(() => setLoading(false), 500);
    return () => clearTimeout(t);
  }, [activeCategory, search]);

  return (
    <main style={{ padding: '20px' }}>

      {/* Search */}
      <input
        placeholder="Search..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />

      {/* Categories */}
      <div>
        {categories.map(c => (
          <button key={c.name} onClick={() => setActiveCategory(c.name)}>
            {c.name}
          </button>
        ))}
      </div>

      {/* Products */}
      {loading ? <p>Loading...</p> : (
        <div>
          {filteredProducts.map(product => (
            <div key={product.id} style={{ border: '1px solid #ccc', margin: 10, padding: 10 }}>

              <img
                src={getImage(product)}
                alt=""
                width="150"
                onError={() => handleImageError(product.id)}
              />

              <h3>{product.title}</h3>
              <p>₹{product.price}</p>

              <button onClick={() => toggleWishlist(product)}>
                {isWishlisted(product.id) ? '❤️' : '🤍'}
              </button>

              <Link to={`/product/${product.id}`}>View</Link>

            </div>
          ))}
        </div>
      )}

    </main>
  );
};

export default Home;
